def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]

    if v1 > v2:
        value = 2019
    elif v2 > v1:
        value = 2018
    else:
        value = None

    return {
        "value": value,
        "trace": {
            "v1": v1,
            "v2": v2,
            "comparison": "2019 > 2018" if v1 > v2 else ("2018 > 2019" if v2 > v1 else "equal"),
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
